void ProjectAutosave::tick()
{
    try {
        if (!m_resume_attempted) {
            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
            if (canvas == nullptr || !canvas->is_initialized())
                return;
            resume_latest();
        }
        adopt_project();
        if (!settle(false) && m_worker.valid())
            return;
        observe_document_change();
        const auto now = Clock::now();
        if (now < m_next_probe)
            return;
        m_next_probe = now + kProbeInterval;
        if (m_plater.model().objects.empty() && m_store->head_id().empty() &&
            m_persistence.document().doc_revision() <= 1) {
            m_state = State::Saved;
            return;
        }
        const std::string model_input = observed_input();
        if (model_input != m_seen_model_input) {
            m_seen_model_input = model_input;
            m_last_edit = now;
            m_state = State::Saving;
        }
        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
        const bool document_due = document_pending &&
            (now - m_last_semantic_edit >= kEditQuietPeriod ||
             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
        // A continuously edited model must not starve the current document.
        // Model capture also publishes the document, so a ready model still
        // takes precedence until the document's maximum delay is reached.
        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
            persist_document(false);
            return;
        }
        const bool model_pending = m_store->head_id().empty() || model_input != m_last_capture_input;
        const bool held          = model_pending && m_capture_hold && m_capture_hold();
        if (model_pending && !held) {
            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
            if (canvas == nullptr || !canvas->is_initialized() ||
                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
                now - m_last_edit < kEditQuietPeriod)
                return;
            capture(false);
        } else if (document_pending) {
            if (!document_due)
                return;
            persist_document(false);
        } else if (!held) {
            m_state = State::Saved;
            m_first_semantic_edit.reset();
        }
    } catch (const std::exception& error) {
        fail(error.what());
    }
}

bool ProjectAutosave::resume_latest()
{
    m_resume_attempted = true;
    try {
        if (!m_plater.model().objects.empty() || !m_plater.get_project_filename(".3mf").empty() ||
            m_persistence.document().doc_revision() > 1)
            return false;
        std::filesystem::path latest;
        std::filesystem::file_time_type latest_time{};
        if (!std::filesystem::is_directory(m_root))
            return false;
        for (const auto& project : std::filesystem::directory_iterator(m_root)) {
            if (!project.is_directory() || !std::filesystem::is_regular_file(project.path() / "HEAD"))
                continue;
            if (m_store && project.path().filename().string() == m_store->project_id())
                continue;
            try {
                if (!authored_head(project.path()))
                    continue;
            } catch (const std::exception& error) {
                BOOST_LOG_TRIVIAL(warning) << "Recent local project index is invalid: " << project.path().string()
                                           << ": " << error.what();
                continue;
            }
            auto modified = std::filesystem::last_write_time(project.path() / "HEAD");
            if (std::filesystem::is_regular_file(project.path() / "current-state.json"))
                modified = std::max(modified, std::filesystem::last_write_time(project.path() / "current-state.json"));
            if (latest.empty() || modified > latest_time) {
                latest = project.path();
                latest_time = modified;
            }
        }
        if (latest.empty())
            return false;
        // The untouched startup draft has no authored state. Release it
        // before opening the durable project selected by the store.
        settle(true);
        m_store.reset();
        auto opened = std::make_unique<ProjectVersionStore>(m_root, latest.filename().string());
        const std::string head = opened->head_id();
        if (head.empty())
            throw std::runtime_error("recent managed project has no current version");
        const auto materialized = opened->materialize(head);
        const auto versions = opened->history();
        const auto selected = std::find_if(versions.begin(), versions.end(), [&head](const auto& item) {
            return item.id == head;
        });
        if (selected == versions.end())
            throw std::runtime_error("recent managed project has no current manifest");
        m_plater.reset();
        m_plater.take_snapshot("Resume local project", UndoRedo::SnapshotType::ProjectSeparator);
        auto strategy = LoadStrategy::Restore;
        if (materialized.empty)
            strategy = strategy | LoadStrategy::AllowEmpty;
        const auto loaded = load_managed_checkpoint(m_plater, materialized, strategy);
        if ((loaded.empty() && !materialized.empty) || (materialized.empty && !m_plater.model().objects.empty()))
            throw std::runtime_error("recent managed project could not be restored");
        m_plater.set_project_filename(wxString::FromUTF8(selected->source_path));
        m_project_name = selected->project_name;
        m_opened_from = selected->opened_from;
        m_opened_digest = selected->opened_digest;
        m_persistence.adopt_managed_state(materialized.semantic_state);
        opened->seed_from_live(m_plater.model());
        m_last_capture_input = observed_input();
        m_seen_model_input = m_last_capture_input;
        m_committed_semantic_revision = m_persistence.document().doc_revision();
        m_seen_semantic_revision = m_committed_semantic_revision;
        m_first_semantic_edit.reset();

        m_print_issues.reset();
        m_workspace.reset();
    }
    event.Skip();
}

bool ShellController::take_opened_files(const std::vector<boost::filesystem::path>& files)
{
    // A drop on the canvas adds; a tool's own load settles its file in the
    // conversation.
    if (m_adding_files || !m_autosave || m_workspace->tool_load_active())
        return false;
    const auto has_extension = [](const boost::filesystem::path& file, const char* extension) {
        return boost::algorithm::iends_with(file.string(), extension);
    };
    // A .3mf opens as a project through OrcaSlicer's load_project, which asks
    // the "Previously opened file" question; files beside it are added to it.
    if (std::any_of(files.begin(), files.end(), [&](const auto& file) { return has_extension(file, ".3mf"); }))
        return false;
    const auto model = std::find_if(files.begin(), files.end(), [&](const auto& file) { return !has_extension(file, ".zip"); });
    if (model == files.end() && !m_zip_opens_project)
        return false;

    const boost::filesystem::path& named = model != files.end() ? *model : files.front();
    BOOST_LOG_TRIVIAL(info) << "JusPrin opens " << files.size() << " file(s) in a new project: " << named.string();
    if (!m_workspace->release_project(std::string(from_path(named.stem()).ToUTF8()))) {
        MessageDialog dialog(m_frame, _L("The open project couldn't be saved, so the file wasn't opened. Try again."),
                             _L("Couldn't open file"), wxOK | wxICON_ERROR);
        Workspace::ScopedDialogListener theirs([&dialog](wxWindow& window, const Workspace::DialogFacts&) {
            return &window == &dialog ? std::optional<int>(Workspace::kShowToPerson) : std::nullopt;
        });
        dialog.ShowModal();
        return true;
    }
    // OrcaSlicer's own load into the new project, as a drop on the canvas
    // adds: the same snapshot, zip and multi-file handling.
    wxArrayString again;
    for (const auto& file : files)
        again.Add(from_path(file));
    add_dropped_files(again);
    m_frame->select_tab(size_t(MainFrame::tp3DEditor));
    return true;
}

bool ShellController::add_dropped_files(const wxArrayString& files)
{
    const bool was_adding = std::exchange(m_adding_files, true);
    const bool loaded     = m_plater->load_files(files);
    m_adding_files        = was_adding;
    return loaded;
}

bool ShellController::open_files_as_new_project(const wxArrayString& files)
{
    const bool was_set  = std::exchange(m_zip_opens_project, true);
    const bool loaded   = m_plater->load_files(files);
    m_zip_opens_project = was_set;
    return loaded;
}

void ShellController::install_drop_target()
{
    m_plater->SetDropTarget(new PrepareDropTarget(*m_frame, *m_plater, [this](const wxArrayString& files) {
        BOOST_LOG_TRIVIAL(info) << "JusPrin adds " << files.size() << " dropped file(s) to the open project";
        return add_dropped_files(files);
    }));
}

